// Runnable Smart Object recipes, checked against the 0.3.0 source validator.
import { readFileSync } from 'node:fs';

const asset = name => `../../assets/examples/blueprints/${name}`;
const read = name => JSON.parse(readFileSync(new URL(`../assets/examples/blueprints/${name}`, import.meta.url), 'utf8'));
const json = name => `\`\`\`json\n${JSON.stringify(read(name), null, 2)}\n\`\`\``;
const fence = (language, value) => `\`\`\`${language}\n${value}\n\`\`\``;
const sources = ['gravewright/maps/blueprints.py', 'gravewright/maps/blueprint_context.py', 'gravewright/maps/blueprint_runtime.py', 'docs/en/map-builder.md', 'docs/pt-BR/map-builder.md'];
const article = (slug, en, pt, sourcePaths = sources) => ({ slug, group: 'examples', sourcePaths, en, pt });
const fixtures = {
  en: `These JSON files describe the stored **Blueprint v2 subdocument**. They are development fixtures, not an installable module, a complete Builder project or a campaign archive. Recreate the nodes in the editor, or use the fixtures in isolated contributor tests. This guide does not assume a JSON import button in the Smart Object editor.\n\nDownload the [complete example bundle](${asset('examples.zip')}) or [the validator](${asset('check-examples.py')}). Every example uses original synthetic data. The host's internal Python evaluator is for source development; browser modules must use the public SDK.`,
  pt: `Estes JSONs descrevem o **subdocumento Blueprint v2** armazenado pelo host. São fixtures para desenvolvimento: não são módulo instalável, projeto completo do Builder ou arquivo de campanha. Recrie os nós no editor ou use os arquivos em testes isolados de contribuição ao host. Este guia não presume um botão de importar JSON no editor de Objetos Inteligentes.\n\nBaixe o [pacote completo de exemplos](${asset('examples.zip')}) ou [o validador](${asset('check-examples.py')}). Todos os exemplos usam dados sintéticos originais. O avaliador Python interno serve ao desenvolvimento do código-fonte; módulos de navegador devem usar o SDK público.`
};

const verification = {
  en: `## Run the fixture in a development installation\n\nExtract the example bundle to \`data/blueprint-examples\` inside a disposable checkout of the documented host. From the checkout root, run:\n\n${fence('sh', 'uv run --locked python data/blueprint-examples/check-examples.py --host .')}\n\nThe checker configures an in-memory database, blocks database queries and calls the real \`clean_blueprint\` and \`evaluate_graph\` functions. It validates all four object kinds, both connection kinds and all 42 node types. This verifies document shape and predicted actions. **Test behavior** is still needed to check real targets, authorization and the complete server chain.`,
  pt: `## Execute a fixture em uma instalação de desenvolvimento\n\nExtraia o pacote de exemplos em \`data/blueprint-examples\`, dentro de um checkout descartável da versão documentada. Na raiz do checkout, execute:\n\n${fence('sh', 'uv run --locked python data/blueprint-examples/check-examples.py --host .')}\n\nO verificador configura banco em memória, bloqueia consultas ao banco e chama as funções reais \`clean_blueprint\` e \`evaluate_graph\`. Ele valida os quatro tipos de objeto, os dois tipos de conexão e os 42 tipos de nó. Isso verifica o formato e as ações previstas. Use também **Test behavior** para conferir alvos reais, autorização e a cadeia completa no servidor.`
};

const testShared = {
  en: `Run **Simulate** to inspect one local event. Then use **Test behavior** to rehearse through the server; its changes are rolled back. Generate or update the scene as GM, then test a synthetic scene with a GM and an authorized player. Verify that a streamer cannot write. After editing the project again, use **Update scene** before expecting different live behavior.`,
  pt: `Use **Simulate** para inspecionar um evento local. Depois use **Test behavior** para ensaiar pelo servidor; as alterações desse ensaio são revertidas. Gere ou atualize a cena como GM e teste uma cena sintética com GM e jogador autorizado. Confira que streamer não consegue gravar. Ao editar novamente o projeto, use **Update scene** antes de esperar mudanças no comportamento da mesa.`
};

function pythonExample(file, event, state, assertion, extra = '') {
  return fence('python', `import json\nfrom pathlib import Path\nfrom gravewright.maps.blueprints import clean_blueprint, evaluate_graph\n\nraw = json.loads(Path("data/blueprint-examples/${file}").read_text(encoding="utf-8"))\nblueprint = clean_blueprint(raw, asset_ids=set(), light_ids=set(), track_ids=set())\nresult = evaluate_graph(blueprint, "${event}", "${state}"${extra})\nprint(result["trace"])\nprint(result["actions"])\n${assertion}`);
}

